using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo(typeof(T)) returns JsonTypeInfo,
//    then cast to JsonTypeInfo<T>.
JsonTypeInfo<Person> personInfo =
    (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));

Console.WriteLine($"Type handled: {personInfo.Type.Name}");
Console.WriteLine($"Kind:         {personInfo.Kind}");

var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized:   {json}");

Person? roundTripped = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {roundTripped}");

// 2) Probe without throwing: TryGetTypeInfo returns false when no metadata
//    is available for the requested type, instead of throwing.
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person)  -> found={found}, info is JsonTypeInfo<Person>: {info is JsonTypeInfo<Person>}");

// Use a resolver that knows about nothing to show the "not found" path.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty — resolves nothing
};

bool missing = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? none);
Console.WriteLine($"TryGetTypeInfo(Person) on empty resolver -> found={missing}, info={none?.GetType().Name ?? "null"}");

// Records
public record Person(string Name, int Age);

